export const MAX_ATTEMPTS = 3;
/** Duration of one processing step. */
export const STEP_MS = 100;
/** Delay before a failed attempt is retried (within the 250 ms to 2 s allowed by the brief). */
export const RETRY_DELAY_MS = 500;
/** A running attempt must renew its lease at least this often; an expired lease is reclaimed. */
export const LEASE_MS = 3000;
/** How often the worker writes its heartbeat. */
export const HEARTBEAT_INTERVAL_MS = 1000;
/** The worker counts as up if its heartbeat is at most this old. */
export const HEARTBEAT_STALE_MS = 3000;
/** Idle poll interval for queued jobs. */
export const POLL_MS = 200;

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A row of the `jobs` table, as selected by SQLite. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  run_after: number;
  lease_until: number;
  created_at: string;
  updated_at: string;
}

/** The public job representation returned by every endpoint. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' && row.result_output !== null ? { output: row.result_output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

