import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase } from './db.ts';
import { HEARTBEAT_STALE_MS, toJob, type JobRow } from './jobs.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const MAX_BODY_BYTES = 64 * 1024;
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const BODY_FIELDS = new Set(['input', 'steps', 'failAttempts']);

const insertJob = db.prepare(`
  INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed,
                    idempotency_key, run_after, lease_until, created_at, updated_at)
  VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, 0, ?, ?)
`);
const selectJobById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const selectJobByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const selectJobs = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const selectHeartbeat = db.prepare("SELECT value FROM meta WHERE key = 'worker_heartbeat'");

interface FieldError {
  field: string;
  message: string;
}

interface Validated {
  input: string;
  steps: number;
  failAttempts: number;
  idempotencyKey: string | undefined;
}

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}

function invalid(res: ServerResponse, fields: FieldError[]): void {
  sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function isIntInRange(v: unknown, min: number, max: number): v is number {
  return typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    req.on('data', (c: Buffer) => {
      size += c.length;
      if (size <= MAX_BODY_BYTES) chunks.push(c);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge: size > MAX_BODY_BYTES }));
    req.on('error', reject);
  });
}

/** Validates a POST /api/jobs request. On failure, sends the 400 response and returns undefined. */
async function parseCreateRequest(req: IncomingMessage, res: ServerResponse): Promise<Validated | undefined> {
  const { text, tooLarge } = await readBody(req);
  const mediaType = String(req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    invalid(res, [{ field: 'body', message: 'Content-Type must be application/json.' }]);
    return undefined;
  }
  if (tooLarge) {
    invalid(res, [{ field: 'body', message: 'The body is too large.' }]);
    return undefined;
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    invalid(res, [{ field: 'body', message: 'The body is not valid JSON.' }]);
    return undefined;
  }
  if (!isPlainObject(parsed)) {
    invalid(res, [{ field: 'body', message: 'The body must be a JSON object.' }]);
    return undefined;
  }

  const fields: FieldError[] = [];
  for (const key of Object.keys(parsed)) {
    if (!BODY_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field.' });
  }

  const { input, steps = 5, failAttempts = 0 } = parsed;
  if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'Required string.' });
  } else if (input.length < 1 || input.length > 1000) {
    fields.push({ field: 'input', message: 'Must be 1 to 1000 characters.' });
  } else if (input.trim() === '') {
    fields.push({ field: 'input', message: 'Must not be only whitespace.' });
  }
  if (!isIntInRange(steps, 1, 20)) fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
  if (!isIntInRange(failAttempts, 0, 5)) fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });

  const key = req.headers['idempotency-key'];
  if (key !== undefined && (typeof key !== 'string' || !IDEMPOTENCY_KEY_RE.test(key))) {
    fields.push({ field: 'Idempotency-Key', message: 'Must match ^[A-Za-z0-9_-]{1,128}$.' });
  }

  if (fields.length > 0) {
    invalid(res, fields);
    return undefined;
  }
  return {
    input: input as string,
    steps: steps as number,
    failAttempts: failAttempts as number,
    idempotencyKey: key as string | undefined,
  };
}

function createJob(v: Validated, res: ServerResponse): void {
  // BEGIN IMMEDIATE takes the write lock up front, so the idempotency lookup and the insert are
  // atomic with respect to the worker and to any other server process.
  db.exec('BEGIN IMMEDIATE');
  let status: number;
  let body: unknown;
  try {
    const existing = v.idempotencyKey === undefined ? undefined : (selectJobByKey.get(v.idempotencyKey) as JobRow | undefined);
    if (existing) {
      const samePayload = existing.input === v.input && existing.steps === v.steps && existing.fail_attempts === v.failAttempts;
      if (samePayload) {
        status = 200;
        body = toJob(existing);
      } else {
        status = 409;
        body = { error: { code: 'idempotency_conflict', message: 'This Idempotency-Key was already used with a different payload.' } };
      }
    } else {
      const now = new Date().toISOString();
      const id = randomUUID();
      insertJob.run(id, v.input, v.steps, v.failAttempts, v.idempotencyKey ?? null, now, now);
      status = 201;
      body = toJob(selectJobById.get(id) as JobRow);
    }
    db.exec('COMMIT');
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
  send(res, status, body);
}

function workerState(): 'up' | 'down' {
  const row = selectHeartbeat.get() as { value: number } | undefined;
  return row !== undefined && Date.now() - Number(row.value) <= HEARTBEAT_STALE_MS ? 'up' : 'down';
}

function notFound(res: ServerResponse): void {
  sendError(res, 404, 'not_found', 'No such resource.');
}

function methodNotAllowed(res: ServerResponse): void {
  sendError(res, 405, 'method_not_allowed', 'The method is not allowed for this resource.');
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res);
    return send(res, 200, { status: 'ok', worker: workerState() });
  }
  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') {
      const rows = selectJobs.all() as unknown as JobRow[];
      return send(res, 200, { jobs: rows.map(toJob) });
    }
    if (method === 'POST') {
      const validated = await parseCreateRequest(req, res);
      if (validated) createJob(validated, res);
      return;
    }
    return methodNotAllowed(res);
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res);
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return notFound(res);
    }
    const row = selectJobById.get(id) as JobRow | undefined;
    if (!row) return notFound(res);
    return send(res, 200, toJob(row));
  }
  notFound(res);
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

server.listen(port, () => console.log(`server listening on ${port}`));

